usage: stage01_samplesheet.py [-h] [--project PROJECT] [--check]
                              [--confirm-exclusions] [--force]
                              [--list-formats] [--model MODEL]
                              [--verify-integrity {none,full}]

Stage 01 — validate the experimental design and emit workflow-ready
samplesheets.

options:
  -h, --help            show this help message and exit
  --project PROJECT     path to projects/<project_title>/ (not needed with
                        --list-formats)
  --check               validate only; write nothing
  --confirm-exclusions  the user has confirmed the excluded samples (contract
                        template T7)
  --force               the user has confirmed overwriting existing
                        samplesheets (T5)
  --list-formats        print the registered per-assay samplesheet formats and
                        exit
  --model MODEL         the exact model id of the agent executing this stage;
                        recorded in the HISTORY.md entry beside the template
                        version (decision 0024)
  --verify-integrity {none,full}
                        none (default): trust the files; stage 00 already
                        checked that every link resolves and carries gzip
                        magic. full: decompress every INCLUDED file before
                        emitting the samplesheet -- the last cheap moment to
                        catch a truncated FASTQ. Above ~10 GB submit this with
                        sbatch; it is not login-node work.
{
  "config_rules": {
    "strandedness": {
      "default": "auto",
      "values": [
        "auto",
        "forward",
        "reverse",
        "unstranded"
      ]
    }
  },
  "formats": {
    "atacseq_bulk": {
      "columns": [
        {
          "column": "sample",
          "from": "design:group"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        },
        {
          "column": "replicate",
          "from": "design:replicate"
        }
      ],
      "source": "nf-core/atacseq 2.1.2 assets/schema_input.json + bin/check_samplesheet.py",
      "status": "active"
    },
    "chipseq_bulk": {
      "columns": [
        {
          "column": "sample",
          "from": "design:group"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        },
        {
          "column": "replicate",
          "from": "design:replicate"
        },
        {
          "column": "antibody",
          "from": "design:antibody"
        },
        {
          "column": "control",
          "from": "lookup:control_group"
        },
        {
          "column": "control_replicate",
          "from": "lookup:control_replicate"
        }
      ],
      "source": "nf-core/chipseq 2.1.0 assets/schema_input.json + bin/check_samplesheet.py",
      "status": "active"
    },
    "cutandrun": {
      "columns": [
        {
          "column": "group",
          "from": "design:group"
        },
        {
          "column": "replicate",
          "from": "design:replicate"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        },
        {
          "column": "control",
          "from": "design:control"
        }
      ],
      "source": "nf-core/cutandrun 3.2.2 assets/schema_input.json",
      "status": "active"
    },
    "methylseq": {
      "columns": [
        {
          "column": "sample",
          "from": "sample_id"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        }
      ],
      "source": "nf-core/methylseq 4.2.0 assets/schema_input.json",
      "status": "active"
    },
    "rnaseq_bulk": {
      "columns": [
        {
          "column": "sample",
          "from": "sample_id"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        },
        {
          "column": "strandedness",
          "from": "config:strandedness"
        }
      ],
      "source": "nf-core/rnaseq 3.26.0",
      "status": "active"
    },
    "scrnaseq": {
      "columns": [
        {
          "column": "sample",
          "from": "sample_id"
        },
        {
          "column": "fastq_1",
          "from": "fastq_1"
        },
        {
          "column": "fastq_2",
          "from": "fastq_2"
        }
      ],
      "source": "nf-core/scrnaseq 4.2.0 assets/schema_input.json",
      "status": "active"
    },
    "spatialvi": {
      "columns": [
        {
          "column": "sample",
          "from": "sample_id"
        },
        {
          "column": "spaceranger_dir",
          "from": "spaceranger_dir"
        }
      ],
      "source": "nf-core/spatialvi ccdfb48 assets/schema_input.json + docs/usage.md",
      "status": "active"
    }
  },
  "ok": true
}

